def float_sort(price):
    """Write a function to sort a tuple by its float element.

    Return a new list containing the items in ``price`` sorted in
    descending order by the float value of their float element
    (typically the second element, e.g. ``('item1', '12.20')``).
    """

    def sort_key(item):
        # The float element is conventionally the second element.
        if isinstance(item, (tuple, list)) and len(item) > 1:
            try:
                return float(item[1])
            except (TypeError, ValueError):
                pass
        # Fall back to the first float-convertible element, if any.
        if isinstance(item, (tuple, list)):
            for element in item:
                try:
                    return float(element)
                except (TypeError, ValueError):
                    continue
        return float(item)

    return sorted(price, key=sort_key, reverse=True)
